// Group/overall status = latest batch's status, with special case for "Not Started" when prior batches exist
const getOverallAnimStatus = rounds => {
  if(!rounds||!rounds.length) return "Not Started";
  const latest = rounds[rounds.length-1];
  const rawStatus = latest.status||"Not Started";
  if(rawStatus==="Not Started" && rounds.length>1) return `Batch ${rounds.length} Pending`;
  return rawStatus;
};
// Color for display status (handles the "Batch N Pending" case)
const getAnimStatusColor = status => {
  if(status&&status.includes("Pending")) return "#6366f1";
  return ANIM_ROUND_STATUS_COLOR[status]||"#6b7280";
};
