// Production lifecycle stages — ordered
const PRODUCTION_STAGES  = ["Planning","Tentative","Approved","Happening Now","Production Wrapped","Completed","Cancelled"];
const PRODUCTION_STATUS  = PRODUCTION_STAGES; // alias for backwards compat
const PROD_STAGE_COLOR   = {
  "Planning":           "#6b7280",
  "Tentative":          "#f59e0b",
  "Approved":           "#10b981",
  "Happening Now":      "#ef4444",
  "Production Wrapped": "#8b5cf6",
  "Completed":          "#06b6d4",
  "Cancelled":          "#374151",
};
// Map legacy status values to new lifecycle stages
const LEGACY_STATUS_MAP = {
  "Confirmed":   "Approved",
  "In Progress": "Happening Now",
};
const normalizeStage = s => LEGACY_STATUS_MAP[s] || (PRODUCTION_STAGES.includes(s) ? s : "Planning");

// Auto-detect stage based on date/time
const autoDetectStage = (production) => {
  const raw = production.status || "Planning";
  const stage = normalizeStage(raw);
  // Never auto-upgrade Completed or Planning
  if(stage === "Completed" || stage === "Planning") return stage;
  if(!production.startTime) return stage;
  const now = new Date();
  const start = new Date(production.startTime);
  const end = production.endTime ? new Date(production.endTime) : new Date(start.getTime()+3600000);
  if(now >= start && now <= end) return "Happening Now";
  if(now > end && stage !== "Completed") return "Production Wrapped";
  return stage;
};
