const mkRound = (label, deadline, reviewers, status="Pending") =>
  ({id:uid(), label, deadline, reviewers, status, notes:""});

const mkDel = (title, editorId, deadline, status, rounds, opts={}) => ({
  id:uid(), title, editorId,
  animatorId: opts.animatorId||null,
  producerId: opts.producerId||null,
  deadline, status, rounds,
  aspectRatio: opts.aspectRatio||"16:9",
  notes: opts.notes||"",
  srtNeeded: opts.srtNeeded||false,
  captionsNeeded: opts.captionsNeeded||false,
  frameLink: opts.frameLink||"",
  framePW: opts.framePW||"",
});

// Review Link deliverables get a specific set of defaults regardless of
// whether they're created manually from the Media Ingest tab or auto-generated
// from a Production's ingest settings — both paths funnel through this.
const mkReviewLinkDeliverable = (project, title, deadline, notes="") => {
  const d = mkDel(title, null, deadline, "Not Started", []);
  d.deliverableType    = "Review Link";
  d.totalRevisions      = "1";
  d.quality             = "HD";
  d.workstream          = project?.workstream||"";
  d.businessUnit        = project?.businessUnit||"";
  d.editorId            = project?.assignees?.["Media Manager"]?.[0]||null;
  d.animatorId          = null;
  d.producerId          = project?.assignees?.["Producer"]?.[0]||null;
  d.distPlatforms       = ["Internal Review"];
  d.useCaseLimitations  = ["Internal Only"];
  d.approvedUses        = ["No external uses"];
  d.keywords            = ["Review link"];
  d.watermark           = true;
  d.notes               = notes;
  return d;
};

// ─── Ingest ⇄ Review Link association helpers ─────────────────────────────────
// A review-link deliverable can be tied to exactly one ingest instance at a
// time, tracked in that ingest's linkedReviewLinkIds (manually managed here)
// or reviewLinkDelIds (bulk-managed by the Production tab's auto-generate
// workflow). Both are checked so either origin shows up in the ingest's list.
const resolveLinkedReviewLinks = (deliverables, ig) => {
  const ids = new Set([...(ig.linkedReviewLinkIds||[]), ...(ig.reviewLinkDelIds||[])]);
  return (deliverables||[]).filter(d=>ids.has(d.id));
};

// Removes delId from whichever of the two id-arrays currently holds it —
// returns just the one field that changed, to be merged into that ingest.
const buildReviewLinkUnlinkPatch = (ig, delId) => {
  if((ig.linkedReviewLinkIds||[]).includes(delId)){
    return { linkedReviewLinkIds: (ig.linkedReviewLinkIds||[]).filter(x=>x!==delId) };
  }
  return { reviewLinkDelIds: (ig.reviewLinkDelIds||[]).filter(x=>x!==delId) };
};

// Default name follows the same pattern as the ingest itself, e.g.
// "26-0008_Ingest002_ReviewLink01" — numbered per-ingest, 2 digits.
const nextReviewLinkName = ig => {
  const n = (ig.linkedReviewLinkIds||[]).length + (ig.reviewLinkDelIds||[]).length + 1;
  return `${ig.ingestName||"Ingest"}_ReviewLink${String(n).padStart(2,"0")}`;
};
// Review links default to a 24-hour turnaround from the ingest's own time.
// Accepts either shape: the per-project ingest card's raw object (datetime)
// or the cross-project tracking sheet's row (ingestDatetime).
const reviewLinkDueDate = ig => {
  const dt = ig.datetime || ig.ingestDatetime;
  return dt ? new Date(new Date(dt).getTime()+24*3600000).toISOString().slice(0,16) : "";
};

// Moves a review-link deliverable from one ingest instance to another within
// the same project. Keys are "manual:<ingestDatesId>" or "production:<productionId>".
// Computes both the "from" removal and "to" addition in a single pass per
// array (ingestDates / productions) so a same-array move can't race itself —
// two separate onUpdateProject calls for the same field would each derive
// from the same stale array and the second would silently undo the first.
const buildReviewLinkReassignPatch = (project, delId, fromKey, toKey) => {
  const patch = {};
  if(!project || !fromKey || !toKey || fromKey===toKey) return patch;
  const [fromSrc, fromId] = fromKey.split(":");
  const [toSrc, toId] = toKey.split(":");
  const stripId = arr => (arr||[]).filter(x=>x!==delId);

  // Keys are always strings ("manual:<id>"), but ingest/production ids are
  // numbers (uid()), so ids must be coerced to strings before comparing.
  if(fromSrc==="manual" || toSrc==="manual"){
    patch.ingestDates = (project.ingestDates||[]).map(x=>{
      const isFrom = fromSrc==="manual" && String(x.id)===fromId;
      const isTo   = toSrc==="manual" && String(x.id)===toId;
      if(!isFrom && !isTo) return x;
      let linked = x.linkedReviewLinkIds||[], bulk = x.reviewLinkDelIds||[];
      if(isFrom){ linked = stripId(linked); bulk = stripId(bulk); }
      if(isTo){ linked = [...linked, delId]; }
      return {...x, linkedReviewLinkIds:linked, reviewLinkDelIds:bulk};
    });
  }
  if(fromSrc==="production" || toSrc==="production"){
    patch.productions = (project.productions||[]).map(p=>{
      const isFrom = fromSrc==="production" && String(p.id)===fromId;
      const isTo   = toSrc==="production" && String(p.id)===toId;
      if(!isFrom && !isTo) return p;
      let linked = p.ingest?.linkedReviewLinkIds||[], bulk = p.ingest?.reviewLinkDelIds||[];
      if(isFrom){ linked = stripId(linked); bulk = stripId(bulk); }
      if(isTo){ linked = [...linked, delId]; }
      return {...p, ingest:{...(p.ingest||{}), linkedReviewLinkIds:linked, reviewLinkDelIds:bulk}};
    });
  }
  return patch;
};


